/* Setting the path directory for all programs, logs, and datasets; Note: This choice flows through to all other programs */

%let path = [redacted-path-adbb6d26e838];
%let path_results = [redacted-path-f43edd645648];
%let path_data = [redacted-path-d76b2bf9ff6c];
%let econ_data = [redacted-path-d485a87a7021];

/* Running the macro program, which contains macros necessariy for the component programs */

%include "&path.\01_build\build_code\99_macros.sas";

/* Running the various programs */

%include "&path.\01_build\build_code\01_callreport.sas";
%include "&path.\01_build\build_code\02_macroecon.sas";
%include "&path.\01_build\build_code\03_irs.sas";
%include "&path.\01_build\build_code\04_branch.sas";
%include "&path.\01_build\build_code\20_combine.sas";
%include "&path.\01_build\build_code\30_dealscan.sas";

/* Creating categorical (numerical) variables for: state, year-quarter */

%categoryvar(datain=commbank3, dataout=commbank3, vars=state date, catvars=stateid dateid);

/* Creating prelim state * year FE categorical variable */

data commbank3;
	set commbank3;
	stateyear = stateid * year;
	run;	

/* Creating categorical (numerical) variables for: state-year */

%categoryvar(datain=commbank3, dataout=commbank3, vars=stateyear, catvars=stateyearid);

data build.final;
	set combined2;
	run; quit;

/* Collecting commercial bank call report data */

proc sql;
	create table commbank as
	select 
		/* Date */ 
		rssd9999 as date2,
		/* Identifiers */
		rssd9001 as rssd, rssd9050 as cert, rssd9017 as name, rssd9010 as name2,
		/* Location */

/* NOTE 3: 	Correcting scaling of capital ratios in certain quarters 							  	*/
/****************************************************************************************************/

/* Loading backup dataset */

data commbank2;
	set build.commbank_backup1;
	run;

/* Fixing certain variables - From 1994 to middle of 2003 ownership percentages are reported times 100 */

%MACRO fixingpercent(var=);
data commbank2;
	set commbank2;
	if year < 2002 and &var > 0 then &var = &var / 100;
	else if year = 2002 and month <= 6 and &var > 0 then &var = &var / 100;
	else if year = 2003 and month <= 6 and &var > 0 then &var = &var / 100;
	else &var = &var;
	run;

/****************************************************************************************************/

/* Loading data */

data commbank4;
	set build.commbank;
	run;

/* Loading data and keeping auditing variables */

	set restatements;
	drop restatement_amount_yr_lag1;
	run;

data build.restatements;
	set restatements;
	run;

/****************************************************************************************************/

/* Pulling daily TED spread data from the St. Louis Fed */

proc import out=ted datafile="&econ_data.\TEDRATE" dbms=xls replace;
	getnames=NO;
	run;

/* Renaming the variables and creating additional date variables */

data ted;
	set ted;
	rename A = date;
	rename B = ted_spread;

/* Pulling data */

data hpi;
	set econ.hpi_fhfa_po_state;
	rename index_sa = hpi_sa;
	rename index_nsa = hpi_nsa;
	rename yr = year;
	rename qtr = quarter;
	run;

/* Creating date variable */

/* Pulling raw data - both seasonally and not seasonally adjusted */

data unemp_nsa;
	set econ.unemp_rate_state_month;
	rename unemp_rate = unemp_nsa;
	run;

data unemp_sa;
	set econ.unemp_rate_sa_state_month;
	rename unemp_rate_sa = unemp_sa;
	run;

/* Merging these two datasets and deleting the interim datasets */

proc sql;
	create table unemp as 
	select a.*,b.unemp_sa
	from unemp_nsa a left join unemp_sa b
	on a.state_code = b.state_code
	and a.date = b.date;

/****************************************************************************************************/

/* Saving quarterly data */

data build.gdp_quarter;
	set econ.Gdp_real_growth_sa_state_quar;
	rename state_code = state;
	rename real_gdp_growth_sa_quarter = ch_gdp_qtr_sa;
	run;

/* Saving yearly data */

data build.gdp_year;
	set econ.Gdp_real_growth_state_annual;
	rename state_code = state;
	rename real_gdp_growth = ch_gdp_yr;

/* Saving the dataset */

data build.ted;
	set ted2;
	run; quit;

	quit;

/* Saving data */

data build.hpi;
	set hpi;
	run;
	quit;

/* SCREEN: Keeping only quarterly observations */

data unemp;
	set unemp;
	if month not in (3,6,9,12) then delete;
	run;

/* Saving data */

data build.unemp;
	set unemp;
	run;
	quit;

/* Saving quarterly data */

data build.gdp_quarter;
	set econ.Gdp_real_growth_sa_state_quar;
	rename state_code = state;
	rename real_gdp_growth_sa_quarter = ch_gdp_qtr_sa;
	run;

/* Saving yearly data */

data build.gdp_year;
	set econ.Gdp_real_growth_state_annual;
	rename state_code = state;
	rename real_gdp_growth = ch_gdp_yr;
	run;

/* Loading the district level data */

data district;
	set collect.irs_audits_1992_2000_districts;
	run;	

/* Loading the district-county matching file */

data matching;
	set collect.idfips;
	run;

/* Fixing the Pacific-Northwest spelling */

data matching;
	set matching;

/* 																									*/
/****************************************************************************************************/

data build.irs_district;
	set district2;
	run;

data build.irs_district_gt1;
	set district_gt1;
	run;

data build.irs_district_gt5;
	set district_gt5;
	run;

/* Pulling data from branch file */

data branch;
	set bank.branch;
	run;

/* Keeping certain variables */

proc sql;
	create table branch2 as
	select year, rssdid, namefull, stnamebr, STALPBR, cntynamb, stcntybr, zipbr, depsumbr, depdom, depsum, brcenm, consold, bkmo, brnum
	from branch;
	quit;

/* Getting the sum of deposits a bank has in a particular county */

proc sql;
	create table branch3 as
	select distinct rssdid, year, namefull, stnamebr, STALPBR, cntynamb, stcntybr, depdom, sum(depsumbr) as depcounty

/* Save the district-share dataset */

data build.district_share;
	set branch5;
	if year > 2005 then delete;
	run;
	quit;

/* Save the competition dataset */

data build.competition;
	set branch_final;
	if year > 2005 then delete;
	run;
	quit;

/* Loading data */

data leniency;
	set collect.alst_cross_states;
	run;	

/* Joining the data */

proc sql;

/* Getting lenderids from lendershares dataset */

proc sql;
	create table lenderheader1 as
	select companyid as lenderid
	from dealscan.lendershares;
	quit;

proc sort data=lenderheader1 out=lenderheader1 nodupkey;
	by lenderid;
	run; quit;

/* Getting information on banks to merge with header */

proc sql;
	create table lenderinfo as
	select company, companyid, parentid, ultimateparentid, city, state, country, region, institutiontype, primarysiccode
	from dealscan.company;

/****************************************************************************************************/

/* Bringing up the Dealscan-call report linking dataset */

data link1;
	set collect.rssd_lenderid;
	if rssd = 0 then delete;
	run;

data link2;
	set collect.rssd_ultimateparentid;	
	if rssd = 0 then delete;
	run;

/* Merging in the bank names from the call reports */

data commbank;
	set build.commbank;
	keep rssd name2 year;

/* Saving the Dealscan loan dataset */

data build.dealscan_full;
	set facility_full;
	run;

data build.dealscan_share;
	set facility_share;
	run;

data build.dealscan_mixed;
	set facility_mixed;
	run;

/* Saving the linking datasets */

data build.link_lenderid;
	set link1;
	run;

data build.link_parentid;
	set link2;
	run;

/* Getting the lending by each bank-year-type, using the allocated version when available and using the full amount if it is not */


proc sql;
	create table facility_mixed as
	select distinct lenderid, lender, year, ltype, sum(lender_share_loan_mixed) as loan_total_mixed
	from facility3
	group by lenderid, year, ltype;
	quit;

/* Merging in the ultimate parentid */

proc sql;
	create table facility_mixed as
	select a.lenderid, a.lender, b.ultimateparentid, b.ultimateparent, year, ltype, loan_total_mixed
	from facility_mixed a left join lenderheader3 b
	on a.lenderid = b.lenderid;
	quit;

/* Bringing up the Dealscan-call report linking dataset */

data link1;
	set collect.rssd_lenderid;
	if rssd = 0 then delete;
	run;

data link2;
	set collect.rssd_ultimateparentid;	
	if rssd = 0 then delete;
	run;

/* Merging in the bank names from the call reports */

data commbank;
	set build.commbank;
	keep rssd name2 year;
	if month ne 12 then delete;
	run; quit;

proc sql;
	create table link1 as
	select a.*,b.name2 as name
	from link1 a left join commbank b
	on a.rssd = b.rssd
	and a.year = b.year;
	quit;	

proc sql;
	create table link2 as
	select a.*,b.name2 as name
	from link2 a left join commbank b
	on a.rssd = b.rssd
	and a.year = b.year;
	quit;
